<?php if($mnState['review_changed']):$mnOld=$mnState['original_review']['snapshot']??null;?><p class="dwf-alert" role="alert"><?= e($vmI('Die aktuelle Vorschau unterscheidet sich von deinem ursprünglichen Prüfstand. Erst ausdrücklich neu prüfen.')) ?></p><?php if($mnOld!==null):?><details><summary><?= e($vmI('Geprüfte Angaben lesen')) ?></summary><p><?= e($mnOld['person']['name']) ?> · <?= e($mnOld['person']['email']) ?></p><p><?= e($mnOld['title']) ?> · <?= e($vmDate($mnOld['date'])) ?></p><div class="voucher-manager-original"><?= e(\Kulturhus\Verein\EventVoucherMail::message($mnOld)['intro']) ?></div></details><?php endif;endif ?>
